const TH = window.THEME;
const BX = 100, BY = 196, BS = 720, NM = 40, RM = 8, PXUM = 40;
const massOf = r => 20*Math.pow(r,3);
function stopAll(el, act) {
  ['pointerdown','mousedown','mouseup','pointerup','keydown','keyup','keypress','dblclick'].forEach(ev =>
    el.addEventListener(ev, e => { e.stopPropagation(); e.preventDefault(); }));
  el.addEventListener('touchstart', e => { e.stopPropagation(); e.preventDefault(); }, {passive:false});
  el.addEventListener('touchend', e => { e.stopPropagation(); e.preventDefault(); act(); el.blur(); }, {passive:false});
  el.addEventListener('click', e => { e.stopPropagation(); e.preventDefault(); act(); el.blur(); });
}
MH.sim({
  params: [
    { key: "T", label: "Nhiệt độ", unit: "K", min: 100, max: 800, step: 10, value: 300 },
    { key: "R", label: "Bán kính hạt", unit: "µm", min: 0.5, max: 2, step: 0.1, value: 1 }
  ],
  setup(p, rand) {
    if (window.__brRoot) window.__brRoot.remove();
    const stage = document.getElementById('stage');
    const root = MH.el('div', { style: { position:'absolute', left:'0', top:'0', width:'1920px', height:'1080px', overflow:'hidden',
      background:`radial-gradient(circle at 30% 20%, ${TH.card} 0%, ${TH.bg} 70%)`, fontFamily:TH.font_body, color:TH.ink } }, stage);
    window.__brRoot = root;
    MH.el('div', { text:'Mô hình chuyển động Brown: hạt bị phân tử va đập', style:{position:'absolute',left:'100px',top:'28px',fontSize:'62px',fontWeight:'800',fontFamily:TH.font_head,color:TH.ink} }, root);
    MH.el('div', { text:'Quan sát: hạt vàng bị phân tử va đập không đều từ mọi phía → chuyển động hỗn loạn, quỹ đạo gấp khúc.', style:{position:'absolute',left:'100px',top:'112px',fontSize:'34px',color:TH.muted} }, root);
    const frame = MH.el('div', { style:{position:'absolute',left:(BX-6)+'px',top:(BY-6)+'px',width:BS+'px',height:BS+'px',border:`6px solid ${TH.ink}`,borderRadius:'10px',background:'#fbfdff',boxShadow:'0 10px 30px rgba(0,0,0,0.15)',overflow:'hidden'} }, root);
    const cv = MH.el('canvas', { width:BS, height:BS, style:{position:'absolute',left:'0',top:'0',width:BS+'px',height:BS+'px'} }, frame);
    cv.width = BS; cv.height = BS;
    const ctx = cv.getContext('2d');
    MH.el('div', { text:'(phân tử và hạt không vẽ theo tỉ lệ)', style:{position:'absolute',left:BX+'px',top:(BY+BS+8)+'px',fontSize:'24px',color:TH.muted,fontStyle:'italic'} }, root);

    const PX = 900, PW = 920;
    const card = MH.el('div', { style:{position:'absolute',left:PX+'px',top:BY+'px',width:PW+'px',height:'250px',background:TH.card,border:`2px solid ${TH.line}`,borderRadius:'18px',padding:'20px 30px',boxSizing:'border-box'} }, root);
    const mkRow = (label, color) => {
      const r = MH.el('div', { style:{display:'flex',justifyContent:'space-between',fontSize:'34px',lineHeight:'52px'} }, card);
      MH.el('span', { text:label, style:{color:TH.muted} }, r);
      return MH.el('span', { text:'', style:{fontWeight:'700',color:color||TH.ink} }, r);
    };
    const rT = mkRow('Nhiệt độ T');
    const rV = mkRow('Tốc độ TB phân tử', '#3b82f6');
    const rM = mkRow('Khối lượng hạt vàng', '#d99a00');
    const rD = mkRow('Hạt cách điểm xuất phát', '#ef4444');

    const s = { root, ctx, n: NM, x:new Float64Array(NM), y:new Float64Array(NM), vx:new Float64Array(NM), vy:new Float64Array(NM),
      bx: BS/2, by: BS/2, bvx: 0, bvy: 0, R: 40*p.R, M: massOf(p.R), x0: BS/2, y0: BS/2,
      trail: [[BS/2, BS/2]], showTrail: true, hits: [], t: 0, k: 0, graph: [], rT, rV, rM, rD, meanSp: 0 };

    const btnRow = MH.el('div', { style:{position:'absolute',left:PX+'px',top:(BY+270)+'px',display:'flex',gap:'20px'} }, root);
    const bstyle = {fontSize:'32px',fontFamily:TH.font_body,fontWeight:'700',padding:'12px 28px',borderRadius:'14px',border:`3px solid ${TH.accent}`,cursor:'pointer'};
    const bTrail = MH.el('button', { type:'button', text:'Tắt vết', style:Object.assign({}, bstyle, {background:TH.accent,color:'#fff'}) }, btnRow);
    bTrail.type = 'button';
    const bClear = MH.el('button', { type:'button', text:'Xoá vết', style:Object.assign({}, bstyle, {background:'#fff',color:TH.accent}) }, btnRow);
    bClear.type = 'button';
    stopAll(bTrail, () => { s.showTrail = !s.showTrail; bTrail.textContent = s.showTrail ? 'Tắt vết' : 'Bật vết'; });
    stopAll(bClear, () => { s.trail = [[s.bx, s.by]]; s.x0 = s.bx; s.y0 = s.by; s.graph = []; });
    const leg = MH.el('div', { style:{position:'absolute',left:(PX+430)+'px',top:(BY+280)+'px',fontSize:'30px',color:TH.muted,display:'flex',gap:'24px',alignItems:'center'} }, root);
    leg.innerHTML = '<span><span style="display:inline-block;width:20px;height:20px;border-radius:50%;background:#3b82f6;vertical-align:middle"></span> phân tử</span><span><span style="display:inline-block;width:28px;height:28px;border-radius:50%;background:#f6c343;border:2px solid #a87a00;vertical-align:middle"></span> hạt Brown</span>';

    const GY = BY + 370, GH = 360;
    const gcard = MH.el('div', { style:{position:'absolute',left:PX+'px',top:GY+'px',width:PW+'px',height:GH+'px',background:TH.card,border:`2px solid ${TH.line}`,borderRadius:'18px'} }, root);
    MH.el('div', { text:'Khoảng cách hạt tới điểm xuất phát (µm) theo thời gian', style:{position:'absolute',left:'24px',top:'12px',fontSize:'30px',fontWeight:'700',color:TH.ink} }, gcard);
    const svg = MH.svg('svg', { width:PW, height:GH-60, style:{position:'absolute',left:'0',top:'58px'} }, gcard);
    s.gx0 = 90; s.gw = PW-130; s.gy0 = 20; s.gh = GH-60-70;
    MH.svg('line', { x1:s.gx0, y1:s.gy0+s.gh, x2:s.gx0+s.gw, y2:s.gy0+s.gh, stroke:TH.ink, 'stroke-width':3 }, svg);
    MH.svg('line', { x1:s.gx0, y1:s.gy0, x2:s.gx0, y2:s.gy0+s.gh, stroke:TH.ink, 'stroke-width':3 }, svg);
    s.gMax = MH.svg('text', { x:s.gx0-10, y:s.gy0+10, 'text-anchor':'end', 'font-size':26, fill:TH.muted, text:'' }, svg);
    MH.svg('text', { x:s.gx0-10, y:s.gy0+s.gh, 'text-anchor':'end', 'font-size':26, fill:TH.muted, text:'0' }, svg);
    MH.svg('text', { x:s.gx0+s.gw, y:s.gy0+s.gh+38, 'text-anchor':'end', 'font-size':26, fill:TH.muted, text:'20 s gần nhất →' }, svg);
    s.gLine = MH.svg('polyline', { points:'', fill:'none', stroke:'#ef4444', 'stroke-width':4, 'stroke-linejoin':'round' }, svg);

    const vr = 260*Math.sqrt(p.T/300);
    for (let i=0;i<NM;i++){
      let ok=false, tx, ty, tries=0;
      while(!ok && tries<500){ tries++;
        tx = RM + rand()*(BS-2*RM); ty = RM + rand()*(BS-2*RM); ok = true;
        if (Math.hypot(tx-s.bx, ty-s.by) < s.R+RM+10) ok=false;
        for (let j=0;j<i && ok;j++) if (Math.hypot(tx-s.x[j],ty-s.y[j])<2*RM+4) ok=false;
      }
      s.x[i]=tx; s.y[i]=ty;
      const sp = vr/Math.SQRT2*Math.sqrt(-2*Math.log(1-rand()*0.999)), a = rand()*Math.PI*2;
      s.vx[i]=sp*Math.cos(a); s.vy[i]=sp*Math.sin(a);
    }
    return s;
  },
  step(s, dt, p, rand) {
    const R = 40*p.R, M = massOf(p.R), m = 1;
    s.R = R; s.M = M;
    s.bx = MH.clamp(s.bx, R, BS-R); s.by = MH.clamp(s.by, R, BS-R);
    const n = s.n, x=s.x, y=s.y, vx=s.vx, vy=s.vy;
    const sub = 3, h = dt/sub;
    for (let k=0;k<sub;k++){
      for (let i=0;i<n;i++){
        x[i]+=vx[i]*h; y[i]+=vy[i]*h;
        if (x[i]<RM){x[i]=RM; vx[i]=Math.abs(vx[i]);} else if (x[i]>BS-RM){x[i]=BS-RM; vx[i]=-Math.abs(vx[i]);}
        if (y[i]<RM){y[i]=RM; vy[i]=Math.abs(vy[i]);} else if (y[i]>BS-RM){y[i]=BS-RM; vy[i]=-Math.abs(vy[i]);}
      }
      s.bx+=s.bvx*h; s.by+=s.bvy*h;
      if (s.bx<R){s.bx=R; s.bvx=Math.abs(s.bvx);} else if (s.bx>BS-R){s.bx=BS-R; s.bvx=-Math.abs(s.bvx);}
      if (s.by<R){s.by=R; s.bvy=Math.abs(s.bvy);} else if (s.by>BS-R){s.by=BS-R; s.bvy=-Math.abs(s.bvy);}
      for (let i=0;i<n;i++){
        for (let j=i+1;j<n;j++){
          const dx=x[i]-x[j], dy=y[i]-y[j], d2=dx*dx+dy*dy;
          if (d2 < 4*RM*RM && d2>1e-9){
            const d=Math.sqrt(d2), nx=dx/d, ny=dy/d;
            const vn=(vx[i]-vx[j])*nx+(vy[i]-vy[j])*ny;
            if (vn<0){ vx[i]-=vn*nx; vy[i]-=vn*ny; vx[j]+=vn*nx; vy[j]+=vn*ny; }
            const ov=(2*RM-d)/2; x[i]+=nx*ov; y[i]+=ny*ov; x[j]-=nx*ov; y[j]-=ny*ov;
          }
        }
        const dx=x[i]-s.bx, dy=y[i]-s.by, d2=dx*dx+dy*dy, rr=R+RM;
        if (d2<rr*rr && d2>1e-9){
          const d=Math.sqrt(d2), nx=dx/d, ny=dy/d;
          const vn=(vx[i]-s.bvx)*nx+(vy[i]-s.bvy)*ny;
          if (vn<0){
            const fm=2*M/(m+M), fb=2*m/(m+M);
            vx[i]-=fm*vn*nx; vy[i]-=fm*vn*ny; s.bvx+=fb*vn*nx; s.bvy+=fb*vn*ny;
            s.hits.push({a:Math.atan2(ny,nx), age:0});
            if (s.hits.length>14) s.hits.shift();
          }
          const ov=rr-d;
          x[i]+=nx*ov*M/(m+M); y[i]+=ny*ov*M/(m+M);
          s.bx-=nx*ov*m/(m+M); s.by-=ny*ov*m/(m+M);
        }
      }
    }
    const damp = Math.exp(-0.8*dt);
    s.bvx*=damp; s.bvy*=damp;
    let e=0; for (let i=0;i<n;i++) e+=vx[i]*vx[i]+vy[i]*vy[i];
    const rms=Math.sqrt(e/n), target=260*Math.sqrt(p.T/300);
    const f=1+0.03*(target/Math.max(rms,1)-1);
    let ms=0;
    for (let i=0;i<n;i++){vx[i]*=f; vy[i]*=f; ms+=Math.hypot(vx[i],vy[i]);}
    s.meanSp = s.meanSp===0 ? ms/n : 0.97*s.meanSp + 0.03*(ms/n);
    for (const hh of s.hits) hh.age+=dt;
    s.t+=dt; s.k++;
    if (s.k%3===0){ s.trail.push([s.bx,s.by]); if (s.trail.length>5000) s.trail.splice(0,1000); }
    if (s.k%6===0){ s.graph.push([s.t, Math.hypot(s.bx-s.x0, s.by-s.y0)/PXUM]); if (s.graph.length>201) s.graph.shift(); }
  },
  draw(s, p, t) {
    const c = s.ctx;
    c.clearRect(0,0,BS,BS);
    c.strokeStyle='rgba(120,140,170,0.12)'; c.lineWidth=1;
    for (let g=40; g<BS; g+=40){ c.beginPath(); c.moveTo(g,0); c.lineTo(g,BS); c.moveTo(0,g); c.lineTo(BS,g); c.stroke(); }
    if (s.showTrail && s.trail.length>1){
      c.strokeStyle='#dc2626'; c.lineWidth=3; c.lineJoin='round'; c.beginPath();
      c.moveTo(s.trail[0][0], s.trail[0][1]);
      for (let i=1;i<s.trail.length;i++) c.lineTo(s.trail[i][0], s.trail[i][1]);
      c.lineTo(s.bx,s.by); c.stroke();
      c.fillStyle='#dc2626'; c.beginPath(); c.arc(s.trail[0][0], s.trail[0][1], 7, 0, 7); c.fill();
    }
    for (let i=0;i<s.n;i++){
      c.fillStyle='#3b82f6'; c.beginPath(); c.arc(s.x[i], s.y[i], RM, 0, 7); c.fill();
      c.fillStyle='rgba(255,255,255,0.6)'; c.beginPath(); c.arc(s.x[i]-2.5, s.y[i]-2.5, 2.5, 0, 7); c.fill();
    }
    const R=s.R;
    const gr=c.createRadialGradient(s.bx-R*0.35, s.by-R*0.35, R*0.1, s.bx, s.by, R);
    gr.addColorStop(0,'#fff3b0'); gr.addColorStop(0.6,'#f6c343'); gr.addColorStop(1,'#d99a00');
    c.fillStyle=gr; c.beginPath(); c.arc(s.bx,s.by,R,0,7); c.fill();
    c.strokeStyle='#a87a00'; c.lineWidth=3; c.stroke();
    for (const hh of s.hits){
      if (hh.age>0.25) continue;
      const a=1-hh.age/0.25;
      c.fillStyle=`rgba(255,80,40,${a})`; c.beginPath();
      c.arc(s.bx+Math.cos(hh.a)*R, s.by+Math.sin(hh.a)*R, 6+6*(1-a), 0, 7); c.fill();
    }
    s.rT.textContent = p.T + ' K';
    s.rV.textContent = '≈ ' + Math.round(s.meanSp*2.066/10)*10 + ' m/s';
    s.rM.textContent = '≈ ' + (s.M<10 ? s.M.toFixed(1) : Math.round(s.M)) + ' × phân tử';
    s.rD.textContent = (Math.hypot(s.bx-s.x0, s.by-s.y0)/PXUM).toFixed(2) + ' µm';
    const G=s.graph;
    let mx=1; for (const g of G) if (g[1]>mx) mx=g[1];
    mx=Math.ceil(mx*1.15);
    s.gMax.textContent = mx;
    if (G.length){
      const t1=G[G.length-1][0];
      let pts=''; for (const g of G){ const xx=s.gx0+s.gw*((g[0]-(t1-20))/20), yy=s.gy0+s.gh*(1-g[1]/mx); if (xx>=s.gx0) pts+=xx.toFixed(1)+','+yy.toFixed(1)+' '; }
      s.gLine.setAttribute('points', pts);
    }
  }
});
